// Build the SOP §4 reference-check email (sent to each referee).
// Inbound payload (from Next.js fireOnboardingTemplate):
//   { onboarderId, template:'reference-request', event, context: {
//     referee_id, referee_name, referee_email,
//     full_name, role_title, onboarding_lead
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const refereeName    = ctx.referee_name     || 'there';
const refereeEmail   = ctx.referee_email    || body.to;
const candidateName  = ctx.full_name        || 'the candidate';
const roleTitle      = ctx.role_title       || 'the role';
const onboardingLead = ctx.onboarding_lead  || 'Erich';

if (!refereeEmail) {
  throw new Error('No referee_email on context — cannot send reference request');
}

const subject = `Reference Check for ${candidateName} | Romega Solutions`;
const body_ = `Hi ${refereeName},

${candidateName} listed you as a reference for the ${roleTitle} role at Romega Solutions and has given permission for us to contact you. We'd be grateful for your feedback.

If possible, please respond within 48 business hours, as delays may affect the candidate's onboarding application. Your feedback will be kept confidential and used only for hiring purposes.

File format: please save your responses as a PDF (not Word) and attach it to your reply. PDF helps preserve formatting and reduce accidental edits.

Thank you in advance for your help.

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;

return [{ json: { to: refereeEmail, subject, body: body_, onboarderId: body.onboarderId, refereeId: ctx.referee_id, template: 'reference-request' } }];
